  (1, 'East Los Angeles College', '38168', 39063389278, '{"blocks":[{"courses":[{"alternatives":[],"catalog_addition":true,"code":"MUSIC 205","units":3,"units_max":null},{"alternatives":[],"catalog_addition":true,"code":"MUSIC 280","units":3,"units_max":null},{"alternatives":[],"catalog_addition":true,"code":"MUSIC 783-1","units":1,"units_max":null},{"alternatives":[],"catalog_addition":true,"code":"MUSIC 783-2","units":1,"units_max":null}],"minimum":null,"name":"COMPLETE THE FOLLOWING FOUR REQUIRED COURSES","option_group":null,"rule":"all","stated":{"max":8,"min":8}},{"courses":[{"alternatives":[],"catalog_addition":false,"code":"MUSIC 561","units":1,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 721","units":1,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 745","units":1,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 775","units":1,"units_max":null}],"minimum":2,"name":"COMPLETE TWO UNITS FROM THE FOLLOWING (COURSES MAY BE REPEATED)","option_group":null,"rule":"choose_units","stated":{"max":2,"min":2}},{"courses":[{"alternatives":[],"catalog_addition":false,"code":"MUSIC 111","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 116","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 118","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 121","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 122","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 141","units":3,"units_max":null}],"minimum":3,"name":"COMPLETE THREE UNITS FROM THE FOLLOWING (ONE CLASS FROM THE FOLLOWING COURSES)","option_group":null,"rule":"choose_units","stated":{"max":3,"min":3}},{"courses":[{"alternatives":[],"catalog_addition":false,"code":"MUSIC 161","units":3,"units_max":null},{"alternatives":[],"catalog_addition":false,"code":"MUSIC 165